-- หัวข้อประเมินตาม JD Rev.01 (16/11/2569) — เฉพาะ JD ที่มีพนักงานใช้ในรอบ 2569
-- ส่วน A งานตาม JD · ส่วน B ทักษะงาน (ระดับหัวหน้า/ผู้จัดการใช้หัวข้อภาวะผู้นำกลางแทนส่วน B) · standard = มาตรฐานระดับ 3
create temp table _n (jd text, sec text, seq int, title text, std text) on commit drop;
insert into _n values
-- MFG-01 ผู้จัดการฝ่ายผลิต
('MFG-01','A',1,'ควบคุมการผลิต คุณภาพ ต้นทุน เวลา และการส่งมอบให้บรรลุตามแผน','ส่งมอบได้ตามแผน ของเสียและต้นทุนอยู่ในเป้า กรณีล่าช้ามีการแก้ไขและแจ้งล่วงหน้า'),
('MFG-01','A',2,'กำหนดนโยบายและวางแผนกำลังการผลิต/กำลังคนของฝ่ายผลิต','มีแผนสอดคล้องแผนการผลิต ใช้กำลังการผลิตและกำลังคนได้คุ้มค่า'),
('MFG-01','A',3,'ปรับปรุงกระบวนการผลิตและเครื่องจักรอย่างต่อเนื่อง','มีโครงการปรับปรุงที่วัดผลได้ และดำเนินการตามแผน'),
('MFG-01','A',4,'วิเคราะห์สาเหตุ แก้ไข และป้องกันปัญหาการผลิต','ปัญหาสำคัญมีการหาสาเหตุและมาตรการป้องกัน ไม่เกิดซ้ำจากสาเหตุเดิม'),
('MFG-01','A',5,'กำกับความปลอดภัยและอาชีวอนามัยในฝ่ายผลิต','ไม่มีอุบัติเหตุร้ายแรงจากการละเลย มาตรการความปลอดภัยถูกปฏิบัติจริง'),
('MFG-01','A',6,'บริหารและพัฒนาบุคลากร พร้อมรายงานการผลิตประจำวัน/เดือน','รายงานครบตรงเวลา ผู้ใต้บังคับบัญชาได้รับมอบหมายงานและวัดผลได้'),
('MFG-01','B',1,'ความรู้กระบวนการผลิตฟิล์ม (เป่า พิมพ์ สลิท กรอ) และเครื่องจักร','ตัดสินใจเรื่องเทคนิคการผลิตได้ถูกต้อง'),
('MFG-01','B',2,'ใช้เครื่องมือปรับปรุงงานและวิเคราะห์ต้นทุน (KPI, Kaizen, 5 Why)','วิเคราะห์ข้อมูลและต้นทุนได้เอง ใช้ผลประกอบการตัดสินใจ'),
-- MFG-03 วิศวกรการผลิต
('MFG-03','A',1,'วิเคราะห์ปัญหาและสาเหตุการผลิตงานเป่า เพื่อลดการสูญเสีย','หาสาเหตุปัญหาที่ได้รับมอบได้ครบ มีมาตรการแก้/ป้องกันที่ใช้ได้จริง'),
('MFG-03','A',2,'จัดทำคู่มือ ขั้นตอน และมาตรฐานการทำงานของงานเป่า','คู่มือ/มาตรฐานเสร็จตามแผน ใช้งานจริงในไลน์'),
('MFG-03','A',3,'พัฒนาผลิตภัณฑ์ (ชริ้งฟิล์ม) และลดต้นทุนการผลิต','โครงการที่ได้รับมอบเดินตามแผน มีผลทดลองสรุปให้ตัดสินใจได้'),
('MFG-03','A',4,'ให้คำแนะนำด้านเทคนิคแก่ผู้ปฏิบัติงาน','ช่วยไลน์ได้ทันเมื่อมีปัญหา ผู้ปฏิบัติงานนำวิธีไปใช้ได้ถูกต้อง'),
('MFG-03','A',5,'ตอบเอกสาร NC / CAR จากลูกค้าภายในและภายนอก','ตอบครบทุกฉบับภายในกำหนด ระบุสาเหตุและมาตรการชัดเจน'),
('MFG-03','B',1,'ความรู้เทคนิคกระบวนการเป่าฟิล์มและเครื่องจักร','ปรับตั้งค่ากระบวนการได้ถูกต้องตามหลักวิศวกรรม'),
('MFG-03','B',2,'ใช้คอมพิวเตอร์วิเคราะห์ข้อมูลและทำรายงาน','สรุปข้อมูลและทำรายงานได้เองถูกต้อง'),
-- PRD-01 หัวหน้าแผนกผลิต ส่วนงานพิมพ์
('PRD-01','A',1,'จัดทำแผนการผลิตของส่วนงานพิมพ์และสลิท','แผนออกทันเวลา สอดคล้องใบความต้องการและกำลังการผลิต'),
('PRD-01','A',2,'ตรวจวัตถุดิบ (สี หมึก ตัวทำละลาย ม้วนก่อนพิมพ์) และวางแผนเบิก','วัตถุดิบพร้อมก่อนเริ่มงาน ไม่มีเครื่องหยุดเพราะของขาด'),
('PRD-01','A',3,'จัดกำลังคนและมอบหมายงานในกะ','ทุกเครื่องมีคนรับผิดชอบ งานเดินตามแผน'),
('PRD-01','A',4,'ติดตามการผลิตและแก้ปัญหาเมื่อไม่ได้ตามแผน','ติดตามทุกงาน วิเคราะห์สาเหตุและแก้ไขเมื่อไม่ได้ตามแผน'),
('PRD-01','A',5,'ควบคุมการปฏิบัติงานและเครื่องจักรให้ถูกต้องมีประสิทธิภาพ','ทำงานตามมาตรฐาน ของเสียไม่เกินเกณฑ์'),
('PRD-01','A',6,'รายงานผลการผลิตและส่งมอบงานให้หน่วยถัดไปตามกำหนด','รายงานครบตรงเวลา ส่งมอบตามกำหนด'),
('PRD-01','B',1,'ความรู้กระบวนการพิมพ์และสลิท','ตัดสินใจเรื่องเทคนิคงานพิมพ์/สลิทได้ถูกต้อง'),
('PRD-01','B',2,'ใช้ Excel วางแผนและสรุปรายงาน','ทำแผนและรายงานได้เองถูกต้อง'),
-- PRD-02 ช่างพิมพ์
('PRD-02','A',1,'ควบคุมเครื่องพิมพ์ ผสมสี/เทียบสีให้ได้ตามมาตรฐานและตัวอย่างลูกค้า','งานพิมพ์ได้ตามแผน สีตรงมาตรฐาน'),
('PRD-02','A',2,'ตรวจวัตถุดิบ สี และวัสดุที่ใช้ผลิต','ตรวจครบก่อนเริ่มงาน ไม่เกิดงานเสียจากวัตถุดิบผิด'),
('PRD-02','A',3,'ดูแลรักษาและทำความสะอาดเครื่องพิมพ์','เครื่องสะอาดพร้อมใช้ ทำครบตามรอบ'),
('PRD-02','A',4,'แก้ไขเครื่องพิมพ์เมื่อเกิดปัญหา','แก้ปัญหาทั่วไปได้เอง เครื่องไม่หยุดนานเกินควร'),
('PRD-02','A',5,'ทำงานตามมาตรฐานและส่งมอบงานให้หน่วยถัดไป','ทำตามมาตรฐานทุกงาน ส่งมอบครบพร้อมเอกสาร'),
('PRD-02','B',1,'ทักษะผสมสีและตั้งเครื่องพิมพ์','ผสมสีและตั้งเครื่องได้ตรงงานโดยไม่ต้องให้คนอื่นแก้'),
('PRD-02','B',2,'ความละเอียดรอบคอบและรับผิดชอบงาน','ตรวจงานก่อนส่งทุกม้วน'),
-- PRD-03 ผู้ช่วยช่างพิมพ์
('PRD-03','A',1,'ผลิตงานตามคำสั่งของผู้บังคับบัญชา','ทำตามคำสั่งถูกต้อง งานเดินได้ตามแผน'),
('PRD-03','A',2,'ตรวจวัตถุดิบ สี และวัสดุที่ใช้ผลิต','เตรียมครบก่อนเริ่มงาน เครื่องไม่ต้องรอ'),
('PRD-03','A',3,'ช่วยผสมสีและเตรียมสีตามที่ช่างพิมพ์มอบหมาย','เตรียมสีถูกต้องตามที่สั่ง ทันเวลา'),
('PRD-03','A',4,'รายงานยอดผลิตแต่ละวัน','รายงานครบถูกต้องทุกวัน'),
('PRD-03','A',5,'ดูแลความสะอาดแผนกและเครื่องจักร','พื้นที่และเครื่องสะอาดเรียบร้อยทุกกะ'),
('PRD-03','B',1,'ความรู้พื้นฐานงานช่างพิมพ์','ทำงานพื้นฐานของเครื่องพิมพ์ได้เองตามขั้นตอน'),
('PRD-03','B',2,'ความละเอียดรอบคอบในงาน','ไม่เกิดของเสียจากความประมาท'),
